package com.yihe.framework.ehr;
import java.util.*;import java.nio.file.*;import org.springframework.jdbc.datasource.*;import org.springframework.transaction.support.TransactionTemplate;
import static com.yihe.framework.ehr.EhrAccess.*;import static com.yihe.framework.ehr.EhrService.*;
public class ArchiveOriginalQueueChecks {
 static int checks;static void check(String name,boolean ok){if(!ok)throw new AssertionError(name);checks++;System.out.println("PASS "+name);}
 static class Model extends AiExamChecks.Fake{@Override @SuppressWarnings("unchecked") public Map<String,Object> compareOriginal(Map<String,Object> body){List<Object> rows=new ArrayList<>();for(Map<String,Object> f:(List<Map<String,Object>>)body.get("fields"))rows.add(map("id",f.get("id"),"sourceId",f.get("sourceId"),"page",f.get("page"),"originalValue",f.get("value"),"originalUnit",f.get("unit"),"originalRange",f.get("referenceRange"),"originalAbnormal",f.get("abnormal"),"quote",str(f.get("label"))+" "+str(f.get("value"))+" "+str(f.get("unit"))+" "+str(f.get("referenceRange"))+" "+str(f.get("abnormal"))));return map("checks",rows);}}
 static class Reader extends DigitalWorkerOriginalCheck{final EhrRepository db;Reader(EhrRepository db,EhrService ehr,DigitalWorkerModelClient model){super(db,ehr,model);this.db=db;}@Override public Map<String,Object> sourceBundle(EhrActor a,String report,int revision){return map("available",true,"pages",db.all("SELECT source_file_id sourceId,1 page,'fixture-scan-image' image FROM a_report_revision_sources WHERE report_id=? AND revision=?",report,revision));}}
 @SuppressWarnings("unchecked") public static void main(String[] args)throws Exception{
  if(!System.getenv("EHR_JDBC_URL").contains("/shayu_3_preview?"))throw new IllegalArgumentException("Preview only");DriverManagerDataSource ds=new DriverManagerDataSource(System.getenv("EHR_JDBC_URL"),System.getenv("EHR_DB_USER"),System.getenv("EHR_DB_PASSWORD"));EhrRepository db=new EhrRepository(ds);EhrService ehr=new EhrService(db);ehr.storage=Files.createTempDirectory("archive-original-check-").toString();EhrOcrService ocr=new EhrOcrService(db,ehr);ReportIntakeChecks.set(ocr,"runtimeMode","synthetic");OcrWorkerQueue ocrq=new OcrWorkerQueue(db,ehr,ocr);ReportIntakeChecks.set(ocrq,"mode","synthetic");Model model=new Model();ArchiveOriginalCheckQueue queue=new ArchiveOriginalCheckQueue(db,ehr,model,new Reader(db,ehr,model));ArchiveAutomationService auto=new ArchiveAutomationService(db,ehr,new ReportMatchingService(db,ehr),new ArchiveAutomationChecks.Assessment(db,ehr));auto.originalQueue=queue;ehr.automation=auto;Map<String,Object> user=db.one("SELECT Org_Code FROM yh_user_reginfo WHERE user_code='LOCAL-PREVIEW'");EhrActor a=new EhrActor("LOCAL-PREVIEW",str(user.get("Org_Code")),"synthetic",true,false);
  new TransactionTemplate(new DataSourceTransactionManager(ds)).execute(tx->{try{
   ArchiveAutomationChecks.Case f=ArchiveAutomationChecks.fixture(db,ehr,ocr,ocrq,a,false,true,false);db.exec("UPDATE a_report_evidence SET ocr_confidence=NULL,raw_fragment=CONCAT('姓名 ',?,' 性别 男 手机 13800000000 脉搏原值不清') WHERE report_id=?",f.name,f.report);auto.process(f.report,1);Map<String,Object> row=db.one("SELECT * FROM a_archive_original_checks WHERE report_id=?",f.report);check("actual_evidence_mismatch_queues_original_read",row!=null&&"queued".equals(row.get("check_status")));queue.request(a,f.report,1,str(row.get("input_etag")),str(row.get("original_stamp")));check("same_snapshot_does_not_duplicate_original_read",db.count("SELECT COUNT(*) FROM a_archive_original_checks WHERE report_id=?",f.report)==1);db.exec("UPDATE a_archive_original_checks SET check_status='running' WHERE report_id=?",f.report);queue.process(row);check("image_recheck_persists_model_quality_evidence","completed".equals(queue.status(a,f.report,1).get("state"))&&num(queue.status(a,f.report,1).get("verifiedItems"))==1);auto.process(f.report,1);Map<String,Object> after=auto.status(a,f.report,1),quality=(Map<String,Object>)((Map<?,?>)after.get("archive")).get("quality");check("model_crosschecked_data_can_advance_to_assessment",num(quality.get("trustedItems"))==1&&after.get("assessmentBatchId")!=null);check("model_crosscheck_never_writes_medical_approval",db.count("SELECT COUNT(*) FROM a_review_records WHERE report_id=?",f.report)==0&&db.count("SELECT COUNT(*) FROM a_report_publications WHERE report_id=?",f.report)==0);check("old_field_exception_resolved_after_automatic_recheck",db.count("SELECT COUNT(*) FROM a_archive_exception_tasks WHERE report_id=? AND category='field' AND task_status='open'",f.report)==0);
   Map<String,Object> field=map("id","i","sourceId","s","page",1,"label","Pulse","value","72","unit","bpm","referenceRange","60-100","abnormal",""),found=map("id","i","sourceId","s","page",1,"originalValue","72","originalUnit","bpm","originalRange","60-100","originalAbnormal","","quote","Pulse 72 bpm 60-100");List<Map<String,Object>> pages=Arrays.asList(map("sourceId","s","page",1,"image","fixture"));check("valid_scan_comparison_is_administrative_only",Boolean.TRUE.equals(ArchiveOriginalCheckQueue.validate(field,found,pages).get("matched"))&&Boolean.FALSE.equals(ArchiveOriginalCheckQueue.validate(field,found,pages).get("medicalReviewed")));found.put("page",2);check("wrong_source_page_cannot_pass",Boolean.FALSE.equals(ArchiveOriginalCheckQueue.validate(field,found,pages).get("matched")));found.put("page",1);found.put("originalUnit","mmHg");check("changed_unit_cannot_pass",Boolean.FALSE.equals(ArchiveOriginalCheckQueue.validate(field,found,pages).get("matched")));found.put("originalUnit","bpm");found.put("quote","Pulse 172 bpm 60-100");check("numeric_substring_cannot_pass",Boolean.FALSE.equals(ArchiveOriginalCheckQueue.validate(field,found,pages).get("matched")));found.put("quote","Pulse 72 bpm 60-100");check("native_page_requires_literal_original_quote",Boolean.FALSE.equals(ArchiveOriginalCheckQueue.validate(field,found,Arrays.asList(map("sourceId","s","page",1,"text","Other report"))).get("matched")));
   db.exec("UPDATE a_health_items SET result_raw='73' WHERE report_id=?",f.report);check("changed_snapshot_does_not_reuse_model_approval",new ArchiveQualityService(db,ehr).modelApproved(f.report,1,hex(digest(bytes(ehr.encode(ehr.snapshot(f.report,1))))),str(row.get("original_stamp"))).isEmpty());return null;
  }catch(Exception error){throw new RuntimeException(error);}finally{tx.setRollbackOnly();}});
  try(java.util.stream.Stream<Path> files=Files.list(Paths.get(ehr.storage))){check("fixture_originals_cleaned",files.count()==0);}Files.delete(Paths.get(ehr.storage));System.out.println("PASS archive original queue checks: "+checks);
 }
}
